'use strict';
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,extra='')=>`<span class="icon ${extra}" style="mask-image:url('assets/icons/${escape(name)}.svg')" aria-hidden="true"></span>`;
const clone=v=>JSON.parse(JSON.stringify(v));
const btn=(action,text,cls='',attrs='')=>`<button data-action="${action}" class="${cls}" ${attrs}>${text}</button>`;
const field=(label,key,value,type='text',attrs='')=>`<label>${label}<input data-field="${key}" type="${type}" value="${escape(value)}" ${attrs}></label>`;
const select=(label,key,value,options,attrs='')=>`<label>${label}<select data-field="${key}" ${attrs}>${options.map(([v,t])=>`<option value="${escape(v)}" ${v===value?'selected':''}>${escape(t)}</option>`).join('')}</select></label>`;
const check=(label,key,value,attrs='')=>`<label class="check-label"><input type="checkbox" data-field="${key}" ${value?'checked':''} ${attrs}>${label}</label>`;
const badge=(text,live=false)=>`<span class="badge ${live?'live':'cached'}">${escape(text)}</span>`;
const empty=text=>`<div class="empty">${icon('folder')}<p>${escape(text)}</p></div>`;
const categories=['discipline','health','learning','focus','projects','college','index'];
const palettes={gold:'#ffd35d',monochrome:'#d5d9df',cyan:'#10c6de',blue:'#509cfb',emerald:'#4adea0',amethyst:'#b184fa',rose:'#f38bbb',amber:'#ffb24f'};
const pages=[['overview','house','Overview'],['achievements','trophy','Achievements'],['history','chart-no-axes-column','Analytics'],['cards','book-open','Card Builder'],['sessions','circuit-board','Session Builder'],['devices','laptop','Devices'],['settings','settings','Settings']];
const headings={overview:['Overview','Focus <em>with purpose</em>','Your next step, prepared here. Your phone runs the session.'],achievements:['Achievements','Current <em>Achievements</em>','Live status of your active streaks, goals, and progress from phone data.'],cards:['Card builder','Card <em>Builder</em>','Create and manage the cards shown on your phone.'],sessions:['Session builder','Session <em>Builder</em>','Plan your focus blocks, review them, and send to your phone.'],history:['Analytics','Your <em>Analytics</em>','Look back, see your progress, and build momentum.'],devices:['Devices','Your <em>devices</em>','Your phone runs the timer. Your tablets show its progress.'],settings:['Settings','Customize <em>your FocusDeck</em>','A calmer setup for your desktop workflow.']};
const exampleCard='FOCUSDECK CARD\nTitle: German vocabulary\nType: hybrid\nCategory: learning\nDescription: Build vocabulary with daily practice.\nUnit: words\nTarget: 1250\nCurrent: 0';
const exampleSession='FOCUSDECK SESSION\nTitle: Calculus practice\nFocus 25m | Review lecture notes\nBreak 5m | Stretch and get water\nFocus 25m | Practice problems\nStopwatch | Review mistakes';
let model={status:{},observed:{},devices:{devices:[],viewers:[]},achievements:{},reports:[],settings:{palette:'gold',motion:'full',density:'comfortable',visuals:true,focus_minutes:25,break_minutes:5},templates:[],deliveries:[],icons:[],builtins:[]};
let page='overview', search='', category='all', showArchived=false, card=null, session=null, rawCommand=null, commandBatch=null, reportKey=null, historyPeriod='week', historyOffset=0, busy=false, pollBusy=false, initialized=false, pasteTexts={}, names={}, savedSettings=null, dirtySettings=false, draftTimer;
let nativeBridge, bridgeReady;
const pendingCalls=new Map();
function api(action,value={}){
  if(window.focusdeckTestBridge) return window.focusdeckTestBridge(action,value);
  return bridgeReady.then(()=>new Promise((resolve,reject)=>{const id=crypto.randomUUID();pendingCalls.set(id,{resolve,reject});nativeBridge.call(id,JSON.stringify({action,value}));}));
}
bridgeReady=new Promise((resolve,reject)=>{
  if(window.focusdeckTestBridge){resolve();return;}
  if(typeof QWebChannel==='undefined'||typeof qt==='undefined'){reject(new Error('Open this interface using the FocusDeck desktop launcher.'));return;}
  new QWebChannel(qt.webChannelTransport,c=>{nativeBridge=c.objects.focusdeck;nativeBridge.replied.connect((id,raw)=>{const p=pendingCalls.get(id);if(!p)return;pendingCalls.delete(id);try{const r=JSON.parse(raw);r.ok?p.resolve(r.value):p.reject(new Error(r.error));}catch(e){p.reject(e);}});resolve();});
});
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',7000);}
function duration(ms,short=false){if(ms===null||ms===undefined||!Number.isFinite(ms))return 'N/A';const n=Math.floor(Math.abs(ms)/1000),h=Math.floor(n/3600),m=Math.floor(n%3600/60),s=n%60;return `${ms<0?'−':''}${h?h+'h ':''}${m}m${short&&h?'':' '+s+'s'}`;}
function date(ms,options={}){if(!ms)return 'Not observed';try{return new Intl.DateTimeFormat('en-GB',{timeZone:model.achievements.zone||undefined,day:'numeric',month:'short',...options}).format(new Date(ms));}catch{return new Date(ms).toLocaleDateString();}}
function age(ms){if(!ms)return 'No observation';const seconds=Math.max(0,Math.floor((Date.now()-ms)/1000));return seconds<60?`${seconds}s ago`:seconds<3600?`${Math.floor(seconds/60)}m ago`:`${Math.floor(seconds/3600)}h ago`;}
const dayFormatters=new Map();
function dayKey(ms){try{const zone=model.achievements.zone||'desktop';if(!dayFormatters.has(zone))dayFormatters.set(zone,new Intl.DateTimeFormat('en-CA',{timeZone:zone==='desktop'?undefined:zone,year:'numeric',month:'2-digit',day:'2-digit'}));return dayFormatters.get(zone).format(new Date(ms));}catch{return new Date(ms).toISOString().slice(0,10);}}
function state(){return model.status.state||{};}
function ledger(){return model.achievements.ledger||{};}
function definitions(){return ledger().definitions||[];}
function summary(id){return (model.achievements.summary||[]).find(s=>s.id===id)||{};}
function progress(d){return d.progress||{};}
function percent(d){const p=progress(d);return p.target_value>0?Math.min(100,Math.max(0,100*(p.current_value||0)/p.target_value)):null;}
function cardIcon(d){const assigned=ledger().cardIcons?.[d.id]?.icon;return assigned||{kind:'builtin',name:d.category==='health'?'dumbbell':d.category==='discipline'?'flame':d.category==='projects'?'cpu':'book-open'};}
function ring(d,size='',draft=false){const appearance=draft&&card?.update_icon?card.icon:cardIcon(d);const source=appearance.kind==='image'?'data:image/png;base64,'+appearance.data_base64:'assets/icons/'+(appearance.name||cardIcon(d).name||'book-open')+'.svg';const ratio=d.progress_enabled?percent(d):(summary(d.id).current==null?null:Math.min(100,100*summary(d.id).current/(summary(d.id).previous_best||summary(d.id).best||summary(d.id).current||1)));const angle=ratio===null?360:3.6*ratio;return `<div class="ring ${size}" style="--angle:${angle}deg"><span class="icon accent-icon card-icon ${appearance.kind==='image'?'custom-image':''}" style="mask-image:url('${escape(source)}')" role="img" aria-label="${escape(d.title||'Card')} icon"></span></div>`;}
function progressBar(d){const pct=percent(d);return `<div class="progress"><span style="width:${pct===null?0:pct}%"></span></div><div class="row between"><small>${escape(progress(d).current_value??0)} / ${escape(progress(d).target_value??'unset')} ${escape(progress(d).unit||'units')}</small><small class="accent">${pct===null?'Target unset':Math.round(pct)+'%'}</small></div>`;}
function sidebarCollapsed(){return model.ui?.sidebar_collapsed??(innerWidth<=800);}
function applyAppearance(){document.body.dataset.sidebar=sidebarCollapsed()?'collapsed':'expanded';const toggle=$('#sidebar-toggle');toggle.setAttribute('aria-expanded',String(!sidebarCollapsed()));toggle.title=sidebarCollapsed()?'Expand sidebar':'Collapse sidebar';toggle.setAttribute('aria-label',toggle.title);toggle.textContent=sidebarCollapsed()?'›':'‹';const s=model.settings;document.documentElement.style.setProperty('--accent',palettes[s.palette]||palettes.gold);const hex=(palettes[s.palette]||palettes.gold).slice(1);document.documentElement.style.setProperty('--rgb',[0,2,4].map(i=>parseInt(hex.slice(i,i+2),16)).join(','));for(const k of ['palette','motion','density','visuals'])document.body.dataset[k]=s[k];}
function navigate(next){if(page==='settings'&&dirtySettings&&next!=='settings'&&!confirm('Leave without applying these settings?'))return;if(page==='settings'&&dirtySettings&&next!=='settings'){model.settings=clone(savedSettings);dirtySettings=false;}page=next;render(true);$('main').scrollTop=0;window.scrollTo(0,0);}
function render(animate=false){
 $('#nav').innerHTML=pages.map(([key,name,title])=>btn('navigate',icon(name)+`<span>${title}</span>`,page===key?'active':'',`data-page="${key}" title="${title}" aria-label="${title}"`)).join('');
 const h=headings[page];$('#eyebrow').textContent=h[0];$('#heading').innerHTML=h[1];$('#subtitle').textContent=h[2];
 $('#content').classList.remove('resizable-grid');$('#content').innerHTML=({overview:overviewPage,achievements:achievementsPage,cards:cardsPage,sessions:sessionPage,history:analyticsPage,devices:devicesPage,settings:settingsPage}[page])();
 decorateIndexUI();document.body.dataset.page=page;decorateDashboardLayouts();runAnalyticsMorph();updateBanner();applyAppearance();$('#content').classList.remove('page-enter');if(animate)requestAnimationFrame(()=>$('#content').classList.add('page-enter'));
}
function updateAchievementResults(){const ds=filteredAchievements();if(!ds.some(d=>d.id===achievementSelection))achievementSelection=ds[0]?.id||null;$('#achievement-count').textContent='('+ds.length+')';$('#achievement-results').innerHTML=ds.map(monitorTile).join('')||empty('No matching achievements.');$('#achievement-detail').innerHTML=ds.length?achievementDetail(ds.find(d=>d.id===achievementSelection)):empty('No matching achievements.');decorateDashboardLayouts();}
function updateBanner(){const s=model.status,connected=s.connected;$('#connection-pill').innerHTML=badge(connected?'Phone connected':'Phone offline',connected);let text='';if(model.demo)text='<div class="banner">ISOLATED PREVIEW • Sample content. Sending, pairing and exports are disabled.</div>';else if(!model.service)text='<div class="banner">Desktop companion is unavailable. Drafts remain local. Start the installed companion here. '+btn('restart-service','Start companion','small')+btn('refresh','Refresh','small')+'</div>';else if(!connected)text='<div class="banner info">Phone offline • Showing cached observations. Its timer continues locally. Connect the phone to the same Wi-Fi and choose CONNECT DESKTOP.</div>';if(s.pending_command)text+=`<div class="banner">A ${escape(s.pending_command.action)} command awaits acknowledgement. Delivery is uncertain; avoid sending it again until the phone reconnects.</div>`;$('#banner').innerHTML=text;}
function pastePanel(){return `<div class="panel paste-panel"><div class="row between"><h2>${icon('sparkles','accent-icon')} Paste from GPT</h2>${badge('Local draft')}</div><textarea id="gpt-paste" placeholder="Paste a FOCUSDECK CARD, SESSION, UPDATE or BATCH…" aria-label="Paste GPT card or session">${escape(pasteTexts[page]||'')}</textarea><div class="row between margin-top">${btn('parse','Create editable draft','outline small')}${btn('paste-clear','Clear','quiet small')}</div><div class="hint">Paste detects the type and opens its editor. Nothing is sent automatically.</div><details><summary>Text format and examples</summary><pre>${escape(exampleCard)}</pre><pre>${escape(exampleSession)}</pre><pre>${escape(exampleRewardSession)}</pre><pre>${escape(exampleUpdate)}</pre><p>Use explicit fields and block lines. Indented text supports all session policies and achievement operations, including rewards, daily objectives and progress updates. Existing FocusDeck JSON also works. Arbitrary prose is not interpreted by an AI service.</p>${btn('copy-format','Copy GPT output instructions','small')}</details></div>`;}
function stat(name,value,symbol){return `<div class="stat">${icon(symbol)}<div><small>${escape(name)}</small><strong>${escape(value)}</strong></div></div>`;}
function totals(reports){return reports.reduce((v,r)=>({focus:v.focus+(r.focused_ms||0),breaks:v.breaks+(r.break_ms||0),done:v.done+(r.blocks||[]).filter(b=>b.outcome==='done').length,sessions:v.sessions+1}),{focus:0,breaks:0,done:0,sessions:0});}
function thisWeek(){const key=dayKey(Date.now());const today=new Date(key+'T12:00:00Z');today.setUTCDate(today.getUTCDate()-(today.getUTCDay()+6)%7);return today.toISOString().slice(0,10);}
function currentSession(){const s=state(),observedSession=model.observed?.state?.session,full=observedSession?.session_id===s.session_id?observedSession:null,active=['active','paused','ready','between','quality','reward','session_reward'].includes(s.phase);if(!active)return `<div class="panel"><h2>Current session</h2>${empty('No session is running. Prepare your next one in Session Builder.')}${btn('new-session',icon('timer')+'Prepare a session','outline')}</div>`;
 const b=full?.blocks?.[s.block_index];return `<div class="panel"><div class="row between"><h2>Current session</h2>${badge(model.status.connected?'FROM PHONE':'CACHED',model.status.connected)}</div><h3>${escape(s.title||'Session')}</h3><p class="muted">${escape(b?.title||'Block '+(Number(s.block_index)+1))} • ${escape(s.phase)}</p><div class="session-track">${Array.from({length:Math.min(s.block_count||0,15)},(_,i)=>`<span class="${i<(s.completed_blocks||0)?'done':''}"></span>`).join('')}</div><small class="muted">${s.timer_mode==='stopwatch'?'PHONE STOPWATCH':'PHONE COUNTDOWN'} • Last observed ${age(s.observed_at_ms)}</small><div class="big-time">${duration(s.timer_mode==='stopwatch'?s.elapsed_active_ms:s.remaining_ms)}</div><div class="metrics"><div><small>Block</small><strong>${(s.block_index??0)+1} / ${s.block_count||0}</strong></div><div><small>Active effort</small><strong>${duration(s.elapsed_active_ms)}</strong></div><div><small>Paused</small><strong>${duration(s.elapsed_paused_ms||0)}</strong></div></div><div class="row wrap margin-top">${sessionControls()}</div></div>`;
}
function sessionControls(){const s=state(),disabled=!model.status.connected||busy||model.status.pending_command?'disabled':'';let actions=[];if(s.phase==='active')actions=[['pause','Pause','outline'],['next','Mark done','outline'],['skip_block','Skip block','skip'],['end_block','End block','danger']];if(['paused','ready','between'].includes(s.phase))actions=[['resume',s.phase==='paused'?'Resume':'Start prepared block','outline']];if(s.phase==='paused')actions.push(['next','Mark done','outline'],['skip_block','Skip block','skip'],['end_block','End block','danger']);if(['reward','session_reward'].includes(s.phase))actions=[['reward_done','Reward taken','outline'],['reward_continue','Continue without reward','']];if(['active','paused','ready','between','quality','reward','session_reward'].includes(s.phase))actions.push(['stop','End session','danger']);return actions.map(([op,label,cls])=>btn('session-control',label,cls+' small',`data-operation="${op}" ${disabled}`)).join('');}
function overviewPage(){const today=dayKey(Date.now()),week=thisWeek(),t=calendarTotals(today,today),w=calendarTotals(week,shiftDate(week,6)),all=totals(model.reports);return `<div class="dashboard-grid kpi-grid"><article class="panel dashboard-card kpi" data-card="overview-summary" data-default-span="12"><div class="analytics-summary">${[['Today’s recorded focus',duration(t.focus),'target'],['This week',duration(w.focus),'chart-no-axes-column'],['Sessions this week',w.sessions,'trophy'],['Blocks marked DONE',t.done,'check'],['All-time focus',duration(all.focus,true),'timer']].map(([n,v,i])=>stat(n,v,i)).join('')}</div></article></div><div class="dashboard-grid">${dashboardCard('timeline','',dailyTimeline(today,true),12)}${dashboardCard('current','',currentSession(),8)}${dashboardCard('week','This Week',lineBars(calendarBuckets('week',calendarRange('week',today)),{id:'overview-week',reference:true}),4)}${dashboardCard('last','',latestReport(),8)}${dashboardCard('paste','',pastePanel(),4)}${dashboardCard('previous','Previous Sessions',recentReports(model.reports.slice(0,8))+btn('navigate','View all →','quiet small','data-page="history"'),8)}${dashboardCard('highlights','Achievement highlights',definitions().filter(d=>!d.archived).slice(0,3).map(d=>`<button class="item" data-action="select-achievement" data-id="${escape(d.id)}">${ring(d)}<div class="grow"><strong>${escape(d.title)}</strong><small>${escape(d.description)}</small>${d.progress_enabled?progressBar(d):`<small>Current streak: ${escape(summary(d.id).current??'N/A')}</small>`}</div></button>`).join('')||empty('Cards appear after synchronization.'),4)}${dashboardCard('actions','Quick actions',btn('new-card','Create achievement card','item outline')+btn('new-session','Prepare a session','item')+deliveryList(3),4)}</div>`;}

function deviceRows(){const ds=[...(model.devices.devices||[]),...(model.devices.viewers||[])];return ds.map(d=>`<div class="item">${icon(d.role==='phone'?'timer':'laptop')}<div class="grow"><strong>${escape(names[d.device_id]||d.name)}</strong><small>${d.role==='phone'?'Session controller • timer authority':'Read-only viewer • no timer controls'}</small></div>${badge('Connected',true)}</div>`).join('')||empty('No devices connected. Pair your phone to begin.');}
function recentReports(rs){return rs.map(r=>btn('select-report',`<div class="grow"><strong>${escape(r.title)}</strong><small>${duration(r.focused_ms)} focus • ${date(r.started_at_ms)}</small></div>${badge(r.status==='complete'?'Completed':'Partial / ended',r.status==='complete')}${icon('chevron-right')}`,'item',`data-key="${escape(r.session_id+':'+r.started_at_ms)}"`)).join('')||empty('No saved sessions yet.');}
function bars(reports,start,count){const d=new Date(start+'T12:00:00Z'),days=Array.from({length:count},(_,i)=>{const x=new Date(d);x.setUTCDate(x.getUTCDate()+i);const key=x.toISOString().slice(0,10);return {label:count<=7?x.toLocaleDateString('en-GB',{weekday:'short',timeZone:'UTC'}):count>14&&i%5!==0?'':String(x.getUTCDate()),value:totals(reports.filter(r=>dayKey(r.started_at_ms)===key)).focus};}),maximum=Math.max(1,...days.map(d=>d.value));return `<div class="bars">${days.map(d=>`<div class="bar-col"><span>${d.value?escape(duration(d.value,true)):''}</span><div class="bar" style="height:${Math.round(d.value/maximum*100)}%"></div><small>${d.label}</small></div>`).join('')}</div><p class="muted margin-top"><small>Saved reports only • ${escape(model.achievements.zone||'Desktop timezone')}</small></p>`;}
function newCard(){card={definition:{id:'card_'+crypto.randomUUID().replaceAll('-','').slice(0,12),title:'',description:'',category:'learning',kind:'daily',streak_enabled:true,progress_enabled:true,daily_participation:false,progress:{current_value:0,target_value:100,unit:'units'}},icon:{kind:'builtin',name:'book-open'},update_icon:true,update_progress:false,isNew:true};rawCommand=null;commandBatch=null;navigate('cards');}
function editCard(id){const d=definitions().find(x=>x.id===id);if(!d)return;card={definition:clone(d),base_hash:d._base_hash,icon:clone(cardIcon(d)),update_icon:false,update_progress:false,isNew:false};rawCommand=null;commandBatch=null;navigate('cards');}
function cardTile(d){const type=d.streak_enabled&&d.progress_enabled?'HYBRID':d.progress_enabled?'PROGRESS':'STREAK';return btn('edit-card',`<div class="row between">${ring(d)}<span class="type-tag">${type}</span></div><strong>${escape(d.title)}</strong><div class="description">${escape(d.description)}</div>${d.streak_enabled?`<small class="accent">${escape(summary(d.id).current??'N/A')} current • Best ${escape(summary(d.id).best??'N/A')}</small>`:''}${d.progress_enabled?progressBar(d):''}`,'achievement '+(card?.definition.id===d.id?'selected':''),`data-id="${escape(d.id)}"`);}
function cardsPage(){const ds=definitions().filter(d=>Boolean(d.archived)===showArchived&&(category==='all'||d.category===category)&&((d.title||'')+' '+(d.description||'')).toLowerCase().includes(search.toLowerCase()));return `<div class="row between wrap"><div class="row wrap"><h2>Phone cards</h2>${badge('Observed '+age(model.achievements.as_of_ms),false)}</div><div class="row wrap">${btn('new-operation','Prepare update','outline')}${btn('new-card',icon('book-open')+'New card','primary')}</div></div><div class="grid cards-layout"><div class="stack"><div><input id="card-search" value="${escape(search)}" placeholder="Search cards…" aria-label="Search achievement cards"><div class="tabs">${['all',...categories].map(c=>btn('filter-category',c==='all'?'All':c[0].toUpperCase()+c.slice(1),'small '+(category===c?'active':''),`data-category="${c}"`)).join('')}${btn('archive-toggle',showArchived?'Show active':'Show archived','small')}</div><div id="card-results" class="card-grid">${ds.map(cardTile).join('')||empty('No cards match. Create one or wait for a phone snapshot.')}</div></div>${pastePanel()}<div class="panel"><h2>Recent deliveries</h2>${deliveryList(5)}</div></div><div>${(rawCommand||commandBatch)?operationEditor():card?cardEditor():`<div class="panel">${empty('Choose a card to edit, or create a new one.')}</div>`}</div></div>`;}
function ordinaryCardEditor(){const d=card.definition,protectedCard=model.builtins.includes(d.id),cap=d.streak_enabled&&d.progress_enabled?'hybrid':d.progress_enabled?'progress':'streak';const fixed=protectedCard?'disabled':'';return `<div class="panel"><div class="row between wrap"><h2>${card.isNew?'Create achievement card':'Edit achievement card'}</h2>${badge('Draft')}${!card.isNew?btn('reload-card','Reload from phone','quiet small'):''}</div>${protectedCard?'<div class="banner info">Built-in measurement rules are protected. Icons and explicit progress updates remain available.</div>':''}<div class="editor-inner"><div class="stack"><div class="form-grid">${field('Title','card.title',d.title,'text',fixed+' maxlength="200"')}${select('Category','card.category',d.category,categories.map(x=>[x,x[0].toUpperCase()+x.slice(1)]),!card.isNew?'disabled':'')}<label class="full">Description<textarea data-field="card.description" maxlength="1000" ${fixed}>${escape(d.description)}</textarea></label>${select('Card type','card.capability',cap,[['streak','Streak only'],['progress','Progress only'],['hybrid','Hybrid • streak + progress']],fixed)}${select('Measurement kind','card.kind',d.kind,[['daily','Daily activity'],['scheduled','Scheduled activity'],['abstinence','Abstinence'],...(!card.isNew&&!['daily','scheduled','abstinence'].includes(d.kind)?[[d.kind,'Automatic • '+d.kind.replaceAll('_',' ')]]:[])],!card.isNew?'disabled':'')}</div><div><h3>Card icon</h3><div class="dropzone" id="icon-drop">${icon('image')}<p>Drop icons or a ZIP pack here</p><small>PNG, JPEG, WebP, ICO or ZIP • transparent icons recommended.<br>Imports are saved to your reusable library; choose one below.</small></div><div class="row margin-top">${btn('pick-icons','Import icons / pack…','small')}${btn('default-icon','Reset icon','quiet small')}</div><div class="card-library-picker">${libraryPicker()}</div><div class="icon-picker">${model.icons.map(name=>btn('builtin-icon',icon(name),'small '+(card.icon.kind==='builtin'&&card.icon.name===name?'selected':''),`data-icon="${name}" title="${name}" aria-label="${name}"`)).join('')}</div></div><div id="progress-fields" class="${d.progress_enabled?'':'hide'}"><h3>Progress configuration</h3><div class="form-grid">${field('Current measured value','card.current',progress(d).current_value??0,'number','min="0" step="any"')}${field('Target (leave blank if unset)','card.target',progress(d).target_value??'','number','min="0" step="any"')}${field('Unit','card.unit',progress(d).unit||'units','text','maxlength="100"')}</div>${card.isNew?'<p class="setting-help">Initial progress is sent when the new card is created.</p>':check('Explicitly update recorded progress / target','card.update_progress',card.update_progress)}<p class="setting-help">Saving a title or icon does not overwrite measured progress. Updating progress does not mark a daily objective complete.</p></div>${d.streak_enabled?`<div><h3>Streak behavior</h3><p class="muted"><small>${d.kind==='abstinence'?'Requires explicit initialization; elapsed time is measured on the phone.':d.kind==='scheduled'?'Participates on days explicitly scheduled by a daily target.':'Daily streaks use recorded activity and the phone’s day boundaries.'}</small></p>${check('Participate in daily objectives','card.daily_participation',d.daily_participation,fixed)}</div>`:''}<div class="row wrap">${d.progress_enabled&&!card.isNew?btn('add-progress','Add measured progress','outline'):''}${btn('save-card-draft','Save draft','')}${btn('send-card','Send changes to phone','primary',busy?'disabled':'')}</div>${!card.isNew?`<div class="row wrap">${btn('card-action',d.archived?'Restore card':'Archive card','small',`data-operation="${d.archived?'restore':'archive'}"`)}${!protectedCard?btn('card-action','Delete card','danger small','data-operation="delete"'):''}${['daily','scheduled'].includes(d.kind)&&d.streak_enabled?btn('card-action','Record activity','outline small','data-operation="event"')+btn('today-target','Today’s objective','outline small'):''}${d.kind==='abstinence'?btn('abstinence-event','Set actual start','outline small','data-operation="initialize"')+btn('abstinence-event','Record streak break','danger small','data-operation="streak_break"'):''}</div>`:''}</div><div class="stack"><div id="card-preview">${phonePreview(d)}</div><div class="panel"><h3>Recorded on phone</h3>${recordedCard(d)}</div></div></div></div>`;}
function phonePreview(d){return `<div class="phone-preview"><p class="preview-label">Phone layout preview • draft</p><div class="preview-card">${ring(d,'large',true)}<h3>${escape(d.title||'Your card title')}</h3><p><small>${escape(d.description||'Your card description')}</small></p>${d.streak_enabled?`<p class="accent">${escape(card?.isNew?'No recorded streak':summary(d.id).current??'N/A')} ${'days'}</p>`:''}${d.progress_enabled?progressBar(d):''}</div><small>This previews appearance; live records come from your phone.</small></div>`;}
function recordedCard(d){const s=summary(d.id),p=progress(definitions().find(x=>x.id===d.id)||{}),history=(ledger().progressHistory||[]).filter(h=>h.achievementId===d.id).slice(-5).reverse();return card.isNew?'<p class="muted">No activity recorded for this draft.</p>':`<div class="metrics"><div><small>Current</small><strong>${escape(s.current??'N/A')}</strong></div><div><small>Best</small><strong>${escape(s.best??'N/A')}</strong></div></div><p class="muted margin-top"><small>Snapshot ${age(model.achievements.as_of_ms)} • ${escape(model.achievements.zone||'Unknown zone')}</small></p>${d.progress_enabled?`<p>${escape(p.current_value??'N/A')} / ${escape(p.target_value??'unset')} ${escape(p.unit||'')}</p>`:''}${history.map(h=>`<div class="delivery-line"><small>${date(h.timestamp)} • ${escape(h.previousValue)} → ${escape(h.newValue)} ${escape(h.unit)}</small></div>`).join('')}`;}
function makeSession(){const minutes=model.settings.focus_minutes||25;return {protocol_version:2,session_id:crypto.randomUUID(),title:'New focus session',created_at:new Date().toISOString(),auto_advance:true,blocks:[{id:'b_'+crypto.randomUUID().slice(0,8),type:'focus',title:'Deep work',timer_mode:'countdown',duration_seconds:minutes*60,reward_policy:{enabled:false}}]};}
function newSession(){session=makeSession();navigate('sessions');}
function sessionPage(){if(!session)session=makeSession();return `<div class="toolbar">${btn('new-session',icon('timer')+'New session','outline')}${btn('save-template',icon('folder')+'Save template')}${btn('send-session',icon('laptop')+'Send session to phone','outline',busy?'disabled':'')}${btn('send-and-start','Send & start new session','outline',busy?'disabled':'')}${btn('start-prepared',icon('zap')+'Start prepared session','primary',(['ready','between'].includes(state().phase)&&model.status.connected&&!busy)?'':'disabled')}</div><div class="grid session-layout"><div class="stack"><div class="panel"><div class="row between"><h2>Session plan</h2>${btn('add-block','＋ Add block','outline small')}</div><div class="form-grid">${field('Session title','session.title',session.title,'text','maxlength="200"')}<div>${check('Start the next block after DONE','session.auto_advance',session.auto_advance)}</div></div><div class="stack margin-top" id="block-list">${session.blocks.map(blockEditor).join('')}</div></div><div class="panel"><h2>Saved templates</h2>${model.templates.map(t=>`<div class="row">${btn('load-template',escape(t.name),'item',`data-id="${escape(t.id)}"`)}${btn('delete-template',icon('ban'),'quiet small',`data-id="${escape(t.id)}" title="Remove template"`)}</div>`).join('')||empty('Save a plan to reuse it. Each delivery gets a fresh session ID.')}</div>${pastePanel()}</div><div class="stack"><div class="panel" id="session-summary">${sessionSummary()}</div>${currentSession()}<div class="panel"><h2>Delivery to phone</h2>${deliveryList(5)}</div><div class="panel"><h2>Session rewards & scoring</h2>${btn('session-policy','Edit conditions, rewards & scoring','outline small')}<p class="muted"><small>Imported reward contracts, quality criteria, weights and session policies are preserved. Simple text plans do not infer rewards.</small></p><details><summary>Inspect full session</summary><pre id="session-json">${escape(JSON.stringify(session,null,2))}</pre></details></div></div></div>`;}
function simplePolicy(b){if(b.reward_contract)return false;const p=b.reward_policy;if(p&&Object.keys(p).some(k=>!['enabled','tiers'].includes(k)))return false;return (!p?.enabled&&!p?.tiers?.length)||(p.tiers?.length===1&&p.tiers[0].condition==='completed'&&p.tiers[0].reward?.text!==undefined&&Object.keys(p.tiers[0].reward).every(k=>['type','text'].includes(k))&&Object.keys(p.tiers[0]).every(k=>['condition','min_focus_ratio','reward'].includes(k)));}
function blockEditor(b,i){const simple=simplePolicy(b),tier=b.reward_policy?.tiers?.[0]||{};return `<div class="block" data-block="${i}" draggable="true"><div class="block-header"><span class="number">${i+1}</span><strong class="accent">${escape(b.title)}</strong><div class="block-tools">${btn('block-up','↑','quiet small',`data-index="${i}" ${i===0?'disabled':''} title="Move up"`)}${btn('block-down','↓','quiet small',`data-index="${i}" ${i===session.blocks.length-1?'disabled':''} title="Move down"`)}${btn('block-copy',icon('folder'),'quiet small',`data-index="${i}" title="Duplicate block"`)}${btn('block-delete',icon('ban'),'danger small',`data-index="${i}" title="Remove block"`)}</div></div><div class="block-editor">${field('Title',`block.${i}.title`,b.title,'text','maxlength="200"')}${select('Block',`block.${i}.type`,b.type,[['focus','Focus'],['break','Break']])}${select('Mode',`block.${i}.timer_mode`,b.timer_mode||'countdown',[['countdown','Countdown'],['stopwatch','Stopwatch']],b.type==='break'?'disabled':'')}${field('Minutes',`block.${i}.minutes`,b.duration_seconds?b.duration_seconds/60:'','number',b.timer_mode==='stopwatch'?'disabled':'min="0.0167" max="1440" step="any"')}</div><details class="block-extra"><summary>Instructions and reward policy</summary><label>Quality criteria (one per line)<textarea data-field="block.${i}.criteria">${escape((b.quality_criteria||[]).join('\n'))}</textarea></label>${simple&&b.type==='focus'?`<div class="form-grid margin-top">${field('Reward text (optional)',`block.${i}.reward_text`,tier.reward?.text||'','text','maxlength="2000"')}${field('Minimum focus ratio (%)',`block.${i}.reward_focus`,tier.min_focus_ratio||0,'number','min="0" max="100" step="any"')}</div><p class="setting-help">Completion reward only. Empty text disables this reward; skipped/ended blocks get no completion reward.</p>`:'<p class="setting-help">Imported conditional policy is preserved. Use the conditions editor to change its fields.</p>'}${b.type==='focus'?btn('block-policy','Edit all conditions & rewards','outline small',`data-index="${i}"`):''}<p class="setting-help">Includes multiple reward tiers, alternatives, comparisons, weights, classification and quality criteria. The complete plan is validated before saving.</p></details></div>`;}
function sessionSummary(){const timed=session.blocks.filter(b=>b.timer_mode!=='stopwatch'),total=timed.reduce((s,b)=>s+(b.duration_seconds||0),0)*1000,focus=timed.filter(b=>b.type==='focus').reduce((s,b)=>s+(b.duration_seconds||0),0)*1000,untimed=session.blocks.filter(b=>b.timer_mode==='stopwatch').length;return `<h2>Session summary</h2><h3>${escape(session.title)}</h3><div class="row between"><div class="stack"><div><small class="muted">Blocks</small><strong>${session.blocks.length}</strong></div><div><small class="muted">Timed focus</small><strong>${duration(focus,true)}</strong></div><div><small class="muted">Breaks</small><strong>${duration(total-focus,true)}</strong></div></div><div class="donut" style="--angle:${total?focus/total*360:0}deg"><div><strong>${duration(total,true)}</strong><small>timed portion</small></div></div></div><p class="muted margin-top">${untimed?`${untimed} stopwatch block${untimed>1?'s':''} • Total finish time is unknown.`:'Countdown blocks advance only when you press DONE.'}</p><div class="divider"></div>${badge(model.status.connected?'Phone ready to receive':'Phone offline',model.status.connected)}<p class="setting-help">Send prepares the session. Start begins the prepared session on the phone.</p>`;}
function deliveryList(limit){const ds=model.deliveries.slice(-limit).reverse();return ds.map(d=>`<div class="delivery-line"><div class="row between"><strong>${escape(d.title||d.kind)}</strong>${badge(d.state==='applied'?'Applied on phone':d.state==='pending'?'Pending':'Needs review',d.state==='applied')}</div>${d.error?`<p class="inline-error">${escape(d.error)}</p>`:''}${d.state==='needs_review'?btn('retry-delivery','Review / retry saved operation','small',`data-id="${escape(d.id)}" ${busy?'disabled':''}`):''}</div>`).join('')||'<p class="muted"><small>No desktop deliveries yet.</small></p>';}
function periodRange(){const today=new Date(dayKey(Date.now())+'T12:00:00Z');let begin=new Date(today),end=new Date(today);if(historyPeriod==='all')return {begin:'1970-01-01',end:'9999-12-31'};if(historyPeriod==='day'){begin.setUTCDate(begin.getUTCDate()+historyOffset);end=new Date(begin);}if(historyPeriod==='week'){begin=new Date(thisWeek()+'T12:00:00Z');begin.setUTCDate(begin.getUTCDate()+7*historyOffset);end=new Date(begin);end.setUTCDate(end.getUTCDate()+6);}if(historyPeriod==='month'){begin=new Date(Date.UTC(today.getUTCFullYear(),today.getUTCMonth()+historyOffset,1,12));end=new Date(Date.UTC(begin.getUTCFullYear(),begin.getUTCMonth()+1,0,12));}if(historyPeriod==='year'){begin=new Date(Date.UTC(today.getUTCFullYear()+historyOffset,0,1,12));end=new Date(Date.UTC(begin.getUTCFullYear(),11,31,12));}return {begin:begin.toISOString().slice(0,10),end:end.toISOString().slice(0,10)};}
function monthlyBars(reports,year=null){const end=year?new Date(Date.UTC(Number(year),11,1)):new Date();const months=Array.from({length:12},(_,i)=>{const d=new Date(Date.UTC(end.getUTCFullYear(),end.getUTCMonth()-11+i,1));const key=d.toISOString().slice(0,7);return {label:d.toLocaleDateString('en-GB',{month:'short',timeZone:'UTC'}),key,value:totals(reports.filter(r=>dayKey(r.started_at_ms).slice(0,7)===key)).focus};}),max=Math.max(1,...months.map(m=>m.value));return `<div class="bars">${months.map(m=>`<div class="bar-col"><span>${m.value?duration(m.value,true):''}</span><div class="bar" style="height:${m.value/max*100}%"></div><small>${m.label}</small></div>`).join('')}</div><p class="muted margin-top"><small>${year?'Monthly focus in '+year:'Last 12 calendar months; totals above cover all history.'}</small></p>`;}
function historyPage(){const range=periodRange(),rs=model.reports.filter(r=>{const key=dayKey(r.started_at_ms);return key>=range.begin&&key<=range.end;}),t=totals(rs),all=totals(model.reports),r=rs.find(r=>r.session_id+':'+r.started_at_ms===reportKey)||rs[0];if(r)reportKey=r.session_id+':'+r.started_at_ms;const count=historyPeriod==='week'?7:historyPeriod==='day'?1:historyPeriod==='month'?new Date(range.end+'T12:00:00Z').getUTCDate():0;return `<div class="panel row between wrap"><div class="tabs">${['day','week','month','year','all'].map(p=>btn('history-period',p[0].toUpperCase()+p.slice(1),'small '+(p===historyPeriod?'active':''),`data-period="${p}"`)).join('')}</div><div class="row">${btn('history-prev','‹','small',historyPeriod==='all'?'disabled':'')}<span>${historyPeriod==='all'?'All recorded history':escape(range.begin+' — '+range.end)}</span>${btn('history-next','›','small',historyPeriod==='all'?'disabled':'')}${btn('history-today','Today','small')}</div></div><div class="panel stats margin-top">${stat('All-time focus',duration(all.focus,true),'target')}${stat('Period focus',duration(t.focus,true),'chart-no-axes-column')}${stat('Sessions',t.sessions,'trophy')}${stat('Blocks marked done',t.done,'check')}${stat('Break time',duration(t.breaks,true),'coffee')}</div><div class="grid overview-top"><div class="panel"><h2>Focus vs breaks</h2><div class="row wrap"><div class="donut" style="--angle:${t.focus+t.breaks?t.focus/(t.focus+t.breaks)*360:0}deg"><div><strong>${duration(t.focus+t.breaks,true)}</strong><small>recorded active time</small></div></div><div class="stack"><p><span class="accent">Focus</span><br><strong>${duration(t.focus,true)}</strong></p><p class="muted">Breaks<br><strong>${duration(t.breaks,true)}</strong></p></div></div></div><div class="panel"><h2>Recorded focus</h2>${count?bars(rs,range.begin,count):monthlyBars(rs,historyPeriod==='year'?range.begin.slice(0,4):null)}</div></div><div class="grid two margin-top"><div class="panel"><div class="row between wrap"><h2>Recent sessions</h2>${btn('delete-all-reports','Delete all logs','danger small')}</div><div class="history-list">${recentReports(rs)}</div></div><div class="panel">${r?reportPanel(r):empty('Choose a recorded session to see its report.')}</div></div>`;}
function reportPanel(r){const done=(r.blocks||[]).filter(b=>b.outcome==='done').length;return `<div class="row between"><h2>Session report</h2>${badge(r.status==='complete'?'Completed':'Partial / ended',r.status==='complete')}</div><h3>${escape(r.title)}</h3><p class="muted"><small>${date(r.started_at_ms,{hour:'2-digit',minute:'2-digit'})} • ${escape(r.recorded_timezone||'Timezone unavailable')}</small></p><div class="metrics"><div><small>Focus</small><strong>${duration(r.focused_ms)}</strong></div><div><small>Break</small><strong>${duration(r.break_ms)}</strong></div><div><small>Done</small><strong>${done} / ${r.planned_block_count??r.blocks.length}</strong></div></div><div class="divider"></div><div class="report-blocks">${r.blocks.map(b=>`<div class="item"><div class="grow"><strong>${escape(b.title)}</strong><small>${escape(b.type)} • ${escape(b.timer_mode||'countdown')} • ${duration(b.active_ms)}</small></div><span class="${b.outcome==='skipped'?'accent':b.outcome==='done'?'green':'red'}">${escape(b.outcome)}</span></div>`).join('')}</div>${reportActions(r.session_id+':'+r.started_at_ms)}<div class="row wrap margin-top">${btn('timeline','View timeline','outline small')}${btn('export-session','Export JSON / CSV','outline small')}${btn('delete-report','Delete this report','danger small')}</div><details><summary>Measured scoring and reward evidence</summary><pre>${escape(JSON.stringify({competition:r.competition,session_reward:r.session_reward,session_reward_result:r.session_reward_result},null,2))}</pre></details>`;}
function devicesPage(){const ds=model.known_devices||[...(model.devices.devices||[]),...(model.devices.viewers||[])].map(d=>({...d,connected:true}));return `<div class="panel"><div class="row">${icon('shield-check','accent-icon')}<p>Your phone owns timer execution, achievements and measurements. The desktop prepares changes; tablets are read-only viewers.</p></div></div><div class="grid device-grid margin-top">${ds.map(d=>`<div class="panel"><div class="row"><div class="device-symbol">${icon(d.role==='phone'?'timer':'laptop')}</div><div><h2>${escape(names[d.device_id]||d.name)}</h2>${badge(d.connected?'Connected':'Offline',Boolean(d.connected))}</div></div><h3 class="${d.role==='phone'?'accent':''}">${d.role==='phone'?'Live session controller':'Read-only viewer'}</h3><p class="muted">${d.role==='phone'?'Runs the timer and records your focus data. GPT sessions and card changes go here.':'Displays phone-derived session, card and history observations. Cannot start, pause or modify sessions.'}</p><p class="muted"><small>Last seen ${age(d.last_seen_ms)} • ${d.connected?'connected to companion':'saved desktop entry'}</small></p><p><small>Device ID</small><br><code class="wordwrap">${escape(d.device_id)}</code></p>${btn('rename-device','Rename on this desktop','small',`data-id="${escape(d.device_id)}"`)}${!d.connected?btn('remove-known-device','Remove saved entry','danger small',`data-id="${escape(d.device_id)}"`):''}</div>`).join('')||`<div class="panel">${empty('No devices connected. Open FocusDeck on the phone and connect to this desktop.')}</div>`}</div><div class="panel row between wrap margin-top"><div><h2>Add a device</h2><p class="muted">Use ordinary pairing for your phone and viewer pairing for a tablet.</p></div><div class="row wrap">${btn('pair-phone','Pair phone','outline')}${btn('pair-viewer','Pair tablet viewer','outline')}${btn('manual-pairing','Manual JSON (phone)','small','data-viewer="false"')}${btn('manual-pairing','Manual JSON (viewer)','small','data-viewer="true"')}${btn('refresh','Refresh connections','')}${btn('restart-service','Restart companion','small')}</div></div><div class="panel margin-top"><h2>Connection help</h2>${!model.status.connected?btn('forget-phone','Forget disconnected phone pairing','danger small'):''}<p class="muted">Devices initiate the connection. To reconnect, open the mobile app → Display & connection → CONNECT DESKTOP. Pairing survives normal app upgrades.</p><p class="muted">A new phone installation has a new identity. Preserve app data during upgrades; replacing the paired controller is a separate recovery action.</p><p class="muted"><small>Wi-Fi signal strength is not measured by the companion and is not displayed here. There is no cloud account.</small></p></div>`;}
function settingsPage(){const s=model.settings;return `<div class="toolbar">${btn('reset-settings','Reset desktop preferences','')}${btn('apply-settings','Apply desktop settings','primary')}</div><div class="grid two"><div class="stack"><div class="panel"><h2>${icon('settings')} General</h2><div class="setting-row"><div><strong>Default focus block</strong><small>Used when creating a new desktop plan.</small></div><input type="number" data-field="settings.focus_minutes" min="1" max="1440" value="${s.focus_minutes}"></div><div class="setting-row"><div><strong>Default break</strong><small>Used when adding a break block.</small></div><input type="number" data-field="settings.break_minutes" min="1" max="1440" value="${s.break_minutes}"></div><p class="setting-help">Krohnkite controls window size and placement. There is no custom title bar; use your normal compositor shortcuts. Closing the window keeps FocusDeck in the system tray. Click its tray icon or launch it again to reopen it; Ctrl+Q or the tray’s Quit FocusDeck exits. Without a system tray, closing exits normally.</p></div><div class="panel"><h2>${icon('laptop')} Device & sync</h2>${deviceRows()}<p class="setting-help">Observation updates pause when the window is hidden. Phone execution continues independently. Tablet presence controls the existing fast viewer updates.</p>${btn('navigate','Manage devices →','outline small','data-page="devices"')}</div><div class="panel"><h2>${icon('shield-check')} Privacy & storage</h2><p>Local desktop storage • no AI API key required.</p><p class="muted"><small>Card/session drafts and display settings are stored separately from phone snapshots. Drafts never count as achievements or session history.</small></p></div></div><div class="stack"><div class="panel"><h2>${icon('palette')} Appearance</h2><strong>Global desktop palette</strong><div class="palette-grid">${Object.entries(palettes).map(([key,color])=>btn('palette',`<i style="background:${color}"></i>${key[0].toUpperCase()+key.slice(1)}`,s.palette===key?'active':'',`data-palette="${key}"`)).join('')}</div><div class="setting-row"><span>Motion effects</span><select data-field="settings.motion">${['full','reduced','off'].map(x=>`<option ${s.motion===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="setting-row"><span>Interface density</span><select data-field="settings.density">${['comfortable','compact','spacious'].map(x=>`<option ${s.density===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="setting-row">${check('Show background artwork','settings.visuals',s.visuals)}</div><p class="setting-help">These preferences apply to the desktop panel. Phone display preferences remain on the phone.</p></div><div class="panel"><h2>${icon('folder')} Data & export</h2>${btn('refresh-logs','Rebuild automatic CSV logs','outline small')}<p class="muted">Export the complete recorded PC archive as JSON and CSV. Existing report evidence and deleted-report filtering are preserved.</p>${btn('export','Choose folder & export archive','outline')}<p class="setting-help">Exports contain real archived measurements. They exclude pairing secrets and desktop drafts.</p></div>${iconLibraryPanel()}<div class="panel"><h2>${icon('sparkles')} GPT paste</h2><p class="muted">Use the compact FocusDeck text format or an existing validated FocusDeck JSON plan. Paste creates an editable draft; sending remains explicit.</p>${btn('copy-format','Copy instructions for your GPT project','outline small')}</div></div></div>`;}
function modal(html){$('#dialog-content').classList.remove('resizable-grid');delete $('#dialog-content').dataset.dashboardDetail;$('#dialog-content').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal();}
async function refresh(){if(pollBusy||layoutGesture||layoutSaving)return;pollBusy=true;try{const next=await api('snapshot',{icon_version:model.icon_version||null});if(next.icon_library===undefined)next.icon_library=model.icon_library||[];if(dirtySettings)next.settings=model.settings;model=next;names=await api('names');if(!initialized){initialized=true;savedSettings=clone(model.settings);card=model.drafts?.card||null;session=model.drafts?.session||null;rawCommand=model.drafts?._active==='command'?model.drafts.command:null;commandBatch=model.drafts?._active==='batch'?model.drafts.batch:null;}applyAppearance();updateBanner();if(!['cards','sessions','settings'].includes(page)&&!document.activeElement?.matches('input,textarea,select')&&!$('#dialog').open&&!layoutEditing)render();}catch(e){toast(e.message);}finally{pollBusy=false;}}
async function parsePaste(){const text=$('#gpt-paste')?.value||'';pasteTexts[page]=text;if(!text.trim())return;try{const result=await api('parse',{text});if(result.index_template){const c=result.draft;card={definition:{...c.definition,streak_enabled:c.configuration!=='PROGRESS_ONLY',progress_enabled:true},index_action:'create',index_configuration:c.configuration||'HYBRID',index_document:c.document,index_source:JSON.stringify(c.document,null,2),icon:{kind:'default'},update_icon:false,isNew:true};rawCommand=null;commandBatch=null;indexEditorPage=0;await saveDraft('card',card);navigate('cards');}else if(result.kind==='card'){card={definition:result.draft,icon:{kind:'builtin',name:'book-open'},update_icon:true,update_progress:false,isNew:!definitions().some(d=>d.id===result.draft.id)};const existing=definitions().find(d=>d.id===result.draft.id);if(existing){card.base_hash=existing._base_hash;card.update_progress=Boolean(result.draft.progress);}rawCommand=null;commandBatch=null;await api('save-draft',{kind:'card',draft:card});navigate('cards');}else if(result.kind==='session'){session=result.draft;await api('save-draft',{kind:'session',draft:session});navigate('sessions');}else if(result.kind==='batch'){commandBatch=result.draft;rawCommand=null;card=null;await saveDraft('batch',commandBatch);navigate('cards');}else{rawCommand=result.draft;commandBatch=null;card=null;await saveDraft('command',rawCommand);navigate('cards');}toast(result.notice);}catch(e){toast(e.message);}}
async function delivery(value){if(busy)return;busy=true;try{toast('Sending to phone…');const result=await api('deliver',value);toast(result.state==='applied'?'Applied on your phone.':result.error||'Delivery needs review.');await refresh();render();}catch(e){toast(e.message);}finally{busy=false;}}
async function loadIcon(value){if(value){card.icon=value;card.update_icon=true;await saveDraft('card',card);render();}}
async function saveDraft(kind,draft){await api('save-draft',{kind,draft});}
function scheduleDraft(){clearTimeout(draftTimer);const kind=page==='cards'?'card':page==='sessions'?'session':null,draft=kind==='card'?card:session;if(!kind||!draft)return;const saved=clone(draft);draftTimer=setTimeout(()=>saveDraft(kind,saved).catch(e=>toast(e.message)),500);}
async function sessionControl(operation){const s=clone(state());let confirmed=true;if(['stop','end_block'].includes(operation))confirmed=confirm(operation==='stop'?'End the whole session? Measured effort is retained; unfinished blocks receive no completion credit.':'End this block without completion credit?');if(operation==='next'&&s.phase==='active')confirmed=confirm('Mark this block DONE? This grants completion credit and evaluates its reward policy.');if(!confirmed||busy)return;busy=true;try{await api('session-control',{operation,session_id:s.session_id,block_index:s.block_index,confirm:confirmed});toast('Phone acknowledged the action.');await refresh();render();}catch(e){toast(e.message);}finally{busy=false;}}
async function actionHandler(button){if(await analyticsAction(button)||await layoutAction(button))return;if(workflowActions.has(button.dataset.action)){await workflowAction(button);return;}const action=button.dataset.action;if(action.startsWith('index-')){await indexAction(button);return;}if(['send-card','send-session','send-and-start','save-template','save-card-draft'].includes(action)){const invalid=$('#content :invalid');if(invalid){invalid.reportValidity();toast('Correct the highlighted field before continuing.');return;}}switch(action){
 case 'navigate':navigate(button.dataset.page);break;
 case 'toggle-sidebar':model.ui=await api('ui',{sidebar_collapsed:!sidebarCollapsed()});applyAppearance();break;
 case 'select-achievement':achievementSelection=button.dataset.id;if(page!=='achievements')navigate('achievements');else render();break;
 case 'achievement-category':achievementCategory=button.dataset.category;render();break;
 case 'achievement-view':achievementView=button.dataset.view;render();break;
 case 'achievement-detail':{achievementSelection=button.dataset.id;const d=definitions().find(x=>x.id===button.dataset.id);if(d){$('#dialog').classList.add('wide-dialog');modal(achievementDetail(d,true));$('#dialog-content').dataset.dashboardDetail='true';decorateDashboardLayouts();}break;}
 case 'achievement-menu':{const d=definitions().find(x=>x.id===button.dataset.id);if(d)modal(`<h2>${escape(d.title)}</h2><div class="stack">${btn('achievement-detail','View all recorded details','outline',`data-id="${escape(d.id)}"`)}${btn('edit-card','Edit in Card Builder','',`data-id="${escape(d.id)}"`)}</div>`);break;}

 case 'refresh':await refresh();render();break;
 case 'new-card':newCard();break;
 case 'library-preview':{const entry=(model.icon_library||[]).find(i=>i.id===button.dataset.id);if(entry)modal(`<h2>${escape(entry.name)}</h2><div class="library-icon" style="padding:25px">${imageMask(entry)}</div><p class="setting-help">Theme-tinted shape. Choose this icon in Card Builder to send it to your phone.</p>`);break;}
 case 'pick-icons':await receiveIcons(await api('pick-icons'));break;
 case 'library-icon':{const entry=(model.icon_library||[]).find(i=>i.id===button.dataset.id);if(card&&entry)await loadIcon(clone(entry.icon));break;}
 case 'library-select-all':iconSelection=new Set((model.icon_library||[]).slice(0,100).map(i=>i.id));render();break;
 case 'library-clear':iconSelection.clear();render();break;
 case 'library-export':{if(!iconSelection.size){toast('Select icons to export.');break;}const r=await api('pick-icons-export',{ids:[...iconSelection]});if(r)toast(`${r.count} icons exported together as a ZIP pack.`);break;}
 case 'library-remove':{if(!iconSelection.size||!confirm('Remove these icons from the desktop library? Icons already assigned to cards remain unchanged.'))break;const r=await api('remove-library-icons',{ids:[...iconSelection]});model.icon_library=r.entries;iconSelection.clear();render();break;}

 case 'edit-card':$('#dialog').close();editCard(button.dataset.id);break;
 case 'reload-card':{const id=card.definition.id;await refresh();editCard(id);toast('Loaded the latest received phone snapshot.');break;}
 case 'filter-category':category=button.dataset.category;render();break;
 case 'archive-toggle':showArchived=!showArchived;render();break;
 case 'parse':await parsePaste();break;
 case 'paste-clear':pasteTexts[page]='';$('#gpt-paste').value='';break;
 case 'save-card-draft':await saveDraft('card',card);toast('Draft saved locally.');break;
 case 'send-card':await delivery({kind:'card',draft:card,title:card.definition.title});break;
 case 'send-command':{const ops=commandBatch||[rawCommand];if(!confirm('Apply these '+ops.length+' reviewed update(s) to the phone? '+(ops.some(c=>c.operation==='delete')?'Includes permanent card/history deletion. ':'')+(ops.some(c=>c.operation==='daily_target')?'Daily objectives replace the target for their date. ':'')+(ops.some(c=>c.operation==='event')?'This records actual activity at the supplied timestamps. ':'')+'Existing receipt IDs will be reused on retry.'))break;await delivery({kind:commandBatch?'batch':'command',draft:commandBatch||rawCommand,title:commandBatch?'Achievement updates':operationNames[rawCommand.operation]});break;}
 case 'pick-icon':await loadIcon(await api('pick-icon'));break;
 case 'default-icon':await loadIcon({kind:'default'});break;
 case 'builtin-icon':await loadIcon({kind:'builtin',name:button.dataset.icon});break;
 case 'card-action':{const op=button.dataset.operation;if(op==='delete'&&!confirm('Permanently delete this card and its card history?'))break;if(op==='event'&&!confirm('Record one completed activity for this card today?'))break;const result=await api('card-action',{operation:op,id:card.definition.id,confirm:op==='delete'});toast(result.state==='applied'?'Phone acknowledged the change.':result.error);await refresh();if(op==='delete'&&result.state==='applied')card=null;render();break;}
 case 'today-target':{const minimum=Number(prompt('How many completed activities should count as today’s objective? This does not set cumulative progress.', '1'));if(!Number.isInteger(minimum)||minimum<1)break;if(!confirm('Set this objective for today, preserving other objectives already scheduled for today?'))break;const r=await api('today-target',{id:card.definition.id,minimum,confirm:true});toast(r.state==='applied'?'Today’s objective applied on phone.':r.error);await refresh();render();break;}
 case 'abstinence-event':{const op=button.dataset.operation,stamp=prompt(op==='initialize'?'Actual start timestamp with timezone (for example 2026-10-08T10:00:00+02:00):':'Actual streak-break timestamp with timezone:',new Date().toISOString());if(!stamp||!confirm('Record this explicit timestamp on your phone?'))break;const r=await api('card-action',{operation:op,id:card.definition.id,timestamp:stamp,confirm:true});toast(r.state==='applied'?'Event recorded on phone.':r.error);await refresh();render();break;}
 case 'new-session':newSession();break;
 case 'add-block':if(session.blocks.length>=100){toast('Maximum 100 blocks.');break;}session.blocks.push({id:'b_'+crypto.randomUUID().slice(0,8),type:'focus',title:'New focus block',timer_mode:'countdown',duration_seconds:model.settings.focus_minutes*60,reward_policy:{enabled:false}});scheduleDraft();render();break;
 case 'block-up':case 'block-down':{const i=+button.dataset.index,j=i+(action==='block-up'?-1:1);if(j>=0&&j<session.blocks.length)[session.blocks[i],session.blocks[j]]=[session.blocks[j],session.blocks[i]];scheduleDraft();render();break;}
 case 'block-copy':{const i=+button.dataset.index;if(session.blocks.length>=100)break;const b=clone(session.blocks[i]);b.id='b_'+crypto.randomUUID().slice(0,8);session.blocks.splice(i+1,0,b);scheduleDraft();render();break;}
 case 'block-delete':if(session.blocks.length<=1){toast('A session needs at least one block.');break;}session.blocks.splice(+button.dataset.index,1);scheduleDraft();render();break;
 case 'save-template':await api('save-template',{draft:session});toast('Template saved.');await refresh();render();break;
 case 'load-template':session=clone(model.templates.find(t=>t.id===button.dataset.id).plan);await saveDraft('session',session);render();break;
 case 'delete-template':if(!confirm('Remove this local template?'))break;await api('delete-template',{id:button.dataset.id});await refresh();render();break;
 case 'send-session':await delivery({kind:'session',draft:session,title:session.title});break;
 case 'send-and-start':if(confirm('Send this plan and start it on your phone now?'))await delivery({kind:'session',draft:session,title:session.title,start:true});break;
 case 'start-prepared':await sessionControl('resume');break;
 case 'session-control':await sessionControl(button.dataset.operation);break;
 case 'retry-delivery':{const d=model.deliveries.find(d=>d.id===button.dataset.id);modal(`<h2>Review saved delivery</h2><p>${escape(d.error||'')}</p><p>Completed steps will not be sent again. An uncertain achievement operation retains its original receipt ID. Pending phone commands must settle before retrying.</p><pre>${escape(JSON.stringify(d.requests,null,2))}</pre>${btn('retry-confirm','Retry the saved operation','outline',`data-id="${escape(d.id)}"`)}`);break;}
 case 'retry-confirm':$('#dialog').close();await delivery({retry_id:button.dataset.id});break;
 case 'select-report':{reportKey=button.dataset.key;const r=model.reports.find(r=>r.session_id+':'+r.started_at_ms===reportKey),range=periodRange();if(r&&(dayKey(r.started_at_ms)<range.begin||dayKey(r.started_at_ms)>range.end)){historyPeriod='all';analyticsAnchor=dayKey(r.started_at_ms);historyOffset=0;}navigate('history');break;}
 case 'history-period':historyPeriod=button.dataset.period;historyOffset=0;render();break;
 case 'history-prev':historyOffset--;render();break;
 case 'history-next':historyOffset++;render();break;
 case 'history-today':historyOffset=0;render();break;
 case 'copy-report':{const r=await api('report-text',{key:button.dataset.key||reportKey});await api('clipboard',{text:r.text});toast('Full report copied for GPT.');break;}
 case 'timeline':{const r=model.reports.find(r=>r.session_id+':'+r.started_at_ms===reportKey);modal(`<h2>Recorded timeline</h2><div class="timeline">${(r.events||[]).map(e=>`<div class="item"><div class="grow"><strong>${escape(e.kind)}</strong><small>${date(e.at_ms,{hour:'2-digit',minute:'2-digit',second:'2-digit'})} • Block ${(e.block_index??0)+1}</small></div><span>${duration(e.active_ms)}</span></div>`).join('')||empty('This older report has no detailed timeline.')}</div>`);break;}
 case 'pair-phone':case 'pair-viewer':case 'regenerate-invite':{const viewer=action==='pair-viewer'||button.dataset.viewer==='true';const r=await api('pair-invite',{viewer});const i=r.invitation;modal(`<h2>${viewer?'Pair a tablet viewer':'Pair your phone'}</h2><p>On the mobile app choose Pair desktop → Scan QR Code. Confirm this host and certificate on the phone. Keep the invitation private.</p><img alt="Short-lived FocusDeck pairing invitation" src="${r.qr_image}" style="display:block;width:min(100%,440px);background:white;margin:auto"><p>Expires ${escape(new Date(i.expires_at_ms).toLocaleTimeString())} • one use • ${escape(i.role)}<br>Desktop ${escape(i.desktop_id)}<br><small class="wordwrap">Certificate ${escape(i.certificate_sha256)}</small></p>${btn('regenerate-invite','New invitation','outline',`data-viewer="${viewer}"`)}${btn('revoke-invite','Revoke invitation','outline',`data-id="${escape(i.invitation_id)}"`)}${btn('manual-pairing','Manual JSON fallback','outline',`data-viewer="${viewer}"`)}`);break;}
 case 'revoke-invite':await api('revoke-invite',{invitation_id:button.dataset.id});modal('<h2>Invitation revoked</h2><p>Create a new invitation to pair.</p>');break;
 case 'manual-pairing':{const r=await api('pairing',{viewer:button.dataset.viewer==='true'});modal(`<h2>Manual JSON pairing</h2><p>These permanent credentials are private. Paste them only into your trusted FocusDeck app.</p><textarea id="pairing-text" readonly>${escape(JSON.stringify(r,null,2))}</textarea>${btn('copy-pairing','Copy pairing credentials','primary margin-top')}`);break;}
 case 'copy-pairing':await api('clipboard',{text:$('#pairing-text').value});toast('Pairing credentials copied.');break;
 case 'remove-known-device':if(confirm('Remove this saved desktop entry? This does not change the phone/tablet’s pairing or data.')){await api('remove-known-device',{id:button.dataset.id});await refresh();render();}break;
 case 'rename-device':{const id=button.dataset.id,name=prompt('Display name on this desktop:',names[id]||'');if(name!==null){names=await api('rename-device',{id,name});render();}break;}
 case 'palette':model.settings.palette=button.dataset.palette;dirtySettings=true;render();break;
 case 'apply-settings':model.settings=await api('settings',model.settings);savedSettings=clone(model.settings);dirtySettings=false;toast('Desktop settings saved.');render();break;
 case 'reset-settings':model.settings={palette:'gold',motion:'full',density:'comfortable',visuals:true,focus_minutes:25,break_minutes:5};dirtySettings=true;render();break;
 case 'export':{const r=await api('pick-export');if(r)toast('Archive exported to your selected folder.');break;}
 case 'copy-format':await api('clipboard',{text:gptOutputInstructions+'\n\n'+exampleCard+'\n\n'+exampleSession+'\n\n'+exampleRewardSession+'\n\n'+exampleUpdate});toast('GPT instructions copied.');break;
}}
document.addEventListener('click',e=>{const b=e.target.closest('button[data-action],g[data-action]');if(b&&!b.disabled)actionHandler(b).catch(e=>toast(e.message));});
$('#dialog-close').addEventListener('click',()=>{$('#dialog').close();$('#dialog-content').innerHTML='';$('#dialog').classList.remove('wide-dialog');});
document.addEventListener('input',e=>{
 const el=e.target;if(el.id==='achievement-search'){achievementSearch=el.value;updateAchievementResults();return;}if(el.id==='gpt-paste'){pasteTexts[page]=el.value;return;}if(el.id==='card-search'){search=el.value;const list=definitions().filter(d=>Boolean(d.archived)===showArchived&&(category==='all'||d.category===category)&&((d.title||'')+' '+(d.description||'')).toLowerCase().includes(search.toLowerCase()));$('#card-results').innerHTML=list.map(cardTile).join('')||empty('No matching cards.');return;}
 const key=el.dataset.field;if(!key){indexInput(el);return;}const value=el.type==='checkbox'?el.checked:el.type==='number'?(el.value===''?null:Number(el.value)):el.value;
 if(key.startsWith('settings.')){model.settings[key.slice(9)]=value;dirtySettings=true;applyAppearance();return;}
 if(key.startsWith('card.')&&card){const k=key.slice(5),d=card.definition;if(k==='capability'){d.streak_enabled=value!=='progress';d.progress_enabled=value!=='streak';if(!d.progress_enabled)card.update_progress=false;d.progress ||= {current_value:0,unit:'units'};render();}else if(k==='current'||k==='target'||k==='unit'){d.progress ||= {};const pk={current:'current_value',target:'target_value',unit:'unit'}[k];if(value===null)delete d.progress[pk];else d.progress[pk]=value;}else if(k==='update_progress')card.update_progress=value;else d[k]=value;const preview=$('#card-preview');if(preview)preview.innerHTML=phonePreview(d);scheduleDraft();}
 if(key.startsWith('session.')&&session){session[key.slice(8)]=value;$('#session-summary').innerHTML=sessionSummary();scheduleDraft();}
 if(key.startsWith('block.')&&session){const [,i,k]=key.split('.'),b=session.blocks[+i];if(k==='minutes')b.duration_seconds=Math.round((value||0)*60);else if(k==='criteria')b.quality_criteria=String(value).split('\n').map(s=>s.trim()).filter(Boolean);else if(k==='reward_text'||k==='reward_focus'){const tier=b.reward_policy?.tiers?.[0]||{},text=k==='reward_text'?String(value):tier.reward?.text||'',minimum=k==='reward_focus'?value:tier.min_focus_ratio||0;b.reward_policy=text?{enabled:true,tiers:[{...tier,condition:'completed',min_focus_ratio:minimum,reward:{...tier.reward,text}}]}:{enabled:false};const advanced=document.querySelector(`[data-field="block.${i}.policy"]`);if(advanced)advanced.value=JSON.stringify(b.reward_policy,null,2);}else if(k==='policy'){try{b.reward_policy=JSON.parse(value);el.setCustomValidity('');}catch{el.setCustomValidity('Invalid reward policy JSON');return;}}else if(k==='timer_mode'||k==='type'){b[k]=value;if(b.type==='break'){b.timer_mode='countdown';b.duration_seconds ||= model.settings.break_minutes*60;}if(b.timer_mode==='stopwatch')delete b.duration_seconds;else b.duration_seconds ||= model.settings.focus_minutes*60;render();}else b[k]=value;const ss=$('#session-summary');if(ss)ss.innerHTML=sessionSummary();const json=$('#session-json');if(json)json.textContent=JSON.stringify(session,null,2);scheduleDraft();}
});
document.addEventListener('change',e=>{if(e.target.dataset.librarySelect){const id=e.target.dataset.librarySelect;if(e.target.checked)iconSelection.add(id);else iconSelection.delete(id);updateLibraryCount();return;}if(e.target.id==='achievement-sort'){achievementSort=e.target.value;render();}if(e.target.id==='achievement-days'){achievementDays=Number(e.target.value);const d=definitions().find(d=>d.id===achievementSelection);if($('#dialog').open){$('#dialog-content').innerHTML=achievementDetail(d,true);decorateDashboardLayouts();}else render();}});
document.addEventListener('paste',e=>{if(e.target.id==='gpt-paste')setTimeout(()=>parsePaste(),0);});
document.addEventListener('dragover',e=>{const drop=e.target.closest('#icon-drop,#icon-pack-drop');if(drop){e.preventDefault();drop.classList.add('over');}if(e.target.closest('[data-block]'))e.preventDefault();});
document.addEventListener('dragleave',e=>e.target.closest('#icon-drop,#icon-pack-drop')?.classList.remove('over'));
let dragging=null;document.addEventListener('dragstart',e=>{if(e.target.closest('input,textarea,select,button')){e.preventDefault();return;}const b=e.target.closest('[data-block]');if(b){dragging=+b.dataset.block;e.dataTransfer.setData('text/plain',String(dragging));}});
document.addEventListener('drop',async e=>{const drop=e.target.closest('#icon-drop,#icon-pack-drop');if(drop){e.preventDefault();drop.classList.remove('over');const files=[...e.dataTransfer.files];if(!files.length)return;if(files.length>100||files.reduce((n,f)=>n+f.size,0)>16*1024*1024){toast('Drop up to 100 icons, 16 MiB total; use Import icons for larger packs.');return;}try{const payload=await Promise.all(files.map(async f=>({name:f.name,data:await readFile(f)})));await receiveIcons(await api('import-icons',{files:payload}));}catch(err){toast(err.message);}return;}const b=e.target.closest('[data-block]');if(b&&dragging!==null){e.preventDefault();const [moved]=session.blocks.splice(dragging,1);session.blocks.splice(+b.dataset.block,0,moved);dragging=null;scheduleDraft();render();}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});
window.addEventListener('resize',applyAppearance);
render(true);window.focusdeckReady=refresh();setInterval(()=>{if(!document.hidden&&!busy)refresh();},3000);
